INSERT INTO `banner_aniversariantes` (`ano`, `mes`, `santo_referencia`, `texto_aniversariantes`, `imagem`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (5, 2026, 'Nossa Senhora de Fátima', '<p><strong>Aniversariantes do mês de Maio ❤️🎊🎉❤️</strong></p><p><br></p><p>Com a graça de Deus temos o prazer e a graça de comemorar o aniversário de nossos colaboradores nesse mês de Maio. </p><p><br></p><p>Pedimos a intercessão de Nossa Senhora de Fátima, que ele interceda pela vida de cada um de vocês. </p><p><br></p><p>Que todos seus sonhos estejam sempre alinhados com os planos de Deus para a sua salvação. </p><p><br></p><p>Gratidão pelo sim de vocês, um Feliz Aniversário, repleto de graças e paz. </p><p><br></p><p><strong>Sintam-se abraçados por cada membro da família da Adoção Espiritual.</strong>\n</p>', X'', '2026-06-01 22:06:43', '2026-06-02 13:20:20', 2);
INSERT INTO `banner_aniversariantes` (`ano`, `mes`, `santo_referencia`, `texto_aniversariantes`, `imagem`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (6, 2026, 'São Pedro', '<p><strong>Aniversariantes do mês de Junho</strong> ❤️🎊🎉❤️ \n\nCom a graça de Deus temos o prazer e a graça de comemorar o aniversário de nossos colaboradores nesse mês de Junho. \n\nPedimos a intercessão de São Pedro, que ele interceda pela vida de cada um de vocês. \n\nQue todos seus sonhos estejam sempre alinhados com os planos de Deus para a sua salvação. \n\nGratidão pelo sim de vocês, um Feliz Aniversário, repleto de graças e paz. \n\n<strong>Sintam-se abraçados por cada membro da família da Adoção Espiritual. </strong></p>', X'', '2026-06-01 22:01:48', '2026-06-02 20:45:01', 2);
INSERT INTO `banner_aniversariantes` (`ano`, `mes`, `santo_referencia`, `texto_aniversariantes`, `imagem`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (7, 2026, 'Nossa Senhora do Carmo', '<p><strong>Aniversariantes do mês de Julho </strong>❤️🎊🎉❤️ </p><p><br></p><p>Com a graça de Deus temos o prazer e a graça de comemorar o aniversário de nossos colaboradores nesse mês de julho. </p><p><br></p><p>Pedimos a intercessão de <strong>Nossa Senhora do Carmo</strong>, que ela interceda pela vida de cada um de vocês. </p><p><br></p><p>Que todos seus sonhos estejam sempre alinhados com os planos de Deus para a sua salvação. </p><p><br></p><p>Gratidão pelo sim de vocês, um Feliz Aniversário, repleto de graças e paz. </p><p><br></p><p>Sintam-se abraçados por cada membro da família da Adoção Espitirual. </p><p><br></p><p><strong>Coordenação da Adoção Espiritual</strong></p>', X'', '2026-07-01 11:26:58', NULL, 2);
INSERT INTO `banner_aniversariantes` (`ano`, `mes`, `santo_referencia`, `texto_aniversariantes`, `imagem`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (8, 2026, 'Santa Dulce', '<p><strong>Aniversariantes do mês de Agosto</strong> ❤️🎊🎉❤️ </p><p><br></p><p>Com a graça de Deus temos o prazer e a graça de comemorar o aniversário de nossos colaboradores nesse mês de Agosto. </p><p><br></p><p>Pedimos a intercessão de <strong>Santa Dulce dos Pobres</strong>, que ela 🙏interceda pela vida de cada um de vocês. </p><p><br></p><p>Que todos seus sonhos estejam sempre alinhados com os planos de Deus para a sua salvação. </p><p><br></p><p>Gratidão pelo sim de vocês, um Feliz Aniversário, repleto de graças e paz. </p><p><br></p><p>Sintam-se abraçados por cada membro da família da Adoção Espitirual. </p><p><br></p><p>❣️*Coordenação da Adoção Espiritual*</p>', X'', '2026-08-03 12:54:05', NULL, 2);
INSERT INTO `banner_aniversariantes` (`ano`, `mes`, `santo_referencia`, `texto_aniversariantes`, `imagem`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (9, 2026, 'Padre Pio', '<p><strong>Aniversariantes do mês de Junho</strong> ❤️🎊🎉❤️ </p><p><br></p><p>Com a graça de Deus temos o prazer e a graça de comemorar o aniversário de nossos colaboradores nesse mês de Junho. </p><p><br></p><p>Pedimos a intercessão de <strong>São Padre Pio</strong>, que ele interceda pela vida de cada um de vocês. </p><p><br></p><p>Que todos seus sonhos estejam sempre alinhados com os planos de Deus para a sua salvação.</p><p><br></p><p>Gratidão pelo sim de vocês, um Feliz Aniversário, repleto de graças e paz. </p><p><br></p><p>❤️ <strong>Coordenação da Adoção Espiritual </strong></p>', X'', '2026-09-02 11:25:03', '2026-09-02 11:28:16', 2);
INSERT INTO `banner_aniversariantes` (`ano`, `mes`, `santo_referencia`, `texto_aniversariantes`, `imagem`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (10, 2026, 'São João Paulo II', '<p><strong>Aniversariantes do mês de Outubro </strong>❤️🎊🎉❤️ </p><p><br></p><p>Com a graça de Deus temos o prazer e a graça de comemorar o aniversário de nossos colaboradores nesse mês de Outubro. </p><p><br></p><p>Pedimos a intercessão de <strong>São João Paulo II</strong>, que ele 🙏interceda pela vida de cada um de vocês. </p><p><br></p><p>Que todos seus sonhos estejam sempre alinhados com os planos de Deus para a sua salvação. </p><p><br></p><p>Gratidão pelo sim de vocês, um Feliz Aniversário, repleto de graças e paz. </p><p><br></p><p>Sintam-se abraçados por cada membro da família da Adoção Espitirual. </p><p><br></p><p>❣️*Coordenação da Adoção Espiritual*</p>', X'', '2026-10-01 22:29:31', NULL, 2);
