INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (844, 17, 'Erival Marques Junior', 'Erival Junior', 'Masculino', 'ermarquesjunior@gmail.com', '18 998078414', 'Outro', 136, '1978-04-04 00:00:00', 'Rua Joaquim Jorge Sobrinho, 135', 'Quatá', '19780000', 25, '$2b$10$irCoWryiujIs5mJ6BSziZOgKEzbwkI6C0VFWm6fNmSYfwLFVTosGy', 'BACHAREL EM TEOLOGIA (Faculdade João Paulo II), CRIAR ARTES, REDES SOCIAIS, COMUNICAÇÃO COM PÚBLICO', 'COOPERAR ATIVAMENTE A FAVOR DA VIDA, INTERCEDER PELA FAMÍLIA DE MODO GERAL, ATENDER A UMA LOCUÇÃO INTERIOR', 'APÓS OS PRIMEIROS CONTATOS COM A FALA DE DOM TIAGO CRESCEU EM MIM O DESEJO DE DOAÇÃO POR ESSA OBRA E O ACOLHIMENTO EM QUE FUI RECEBIDO POR DÉBORA E TODOS QUE JÁ COMUNGAVAM DESSA GRAÇA, ME FEZ SENTIR POR LAÇO ESPIRITUAL PARTE DE UMA GRANDE FAMÍLIA.', NULL, NULL, '2026-06-28 22:38:57', 0, 'Ativo', '2024-01-06 17:27:43', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (845, 18, 'Monica Baptista de Oliveira', 'Monica Oliveira', 'Feminino', 'crochetandoarteemlinha@gmail.com', '21980375313', 'Outro', 105, '1971-09-07 00:00:00', 'Rua Cobé 569 casa 3 Bangu', 'Rio de Janeiro', '21820200', 19, '$2b$10$uDyUfGYDAsiTShe7P93tLe3Vy.LOMQ.tTL5QZ/d6tgQDxdvupDSza', 'Sou empreendedora trabalho com artesanato ( crochê)', 'Tenho certeza que a 28 anos atrás alguém rezou pela minha filha, no início foi rejeitada pela família paterna mas eu resisti bravamente e no dia que fui ter ela o carro quebrou a caminho do hospital, médico marcou e não foi, maternidade não aceitou, tive que percorrer várias até achar uma que me aceitou. Daí minha filha levou 32 hs para nascer bebeu água de parto e ficou 17 dias internada . só que antes tive um sonho com Nossa Senhora  e ela me falou que a criança que eu estava esperando ia nascer e ia ser muito abençoado e protejida . E depois de passar por isso tudo a minha filha nao ficou com nenhuma sequela.\r\nQuando conheci a adoção Espiritual senti logo no coração que deveria rezar por outras crianças.  Salve Maria!!!', '', NULL, NULL, '2026-06-28 22:38:58', 0, 'Ativo', '2024-01-08 00:05:06', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (846, 19, 'Claudia Ventura Nascimento', 'Claudia Nascimento', 'Feminino', 'venturanascimento2@gmail.com', '(21) 98679-3832', 'Outro', 22, '1964-03-24 00:00:00', 'Rua: Alcebiades Sodré n° 21a', 'Rio de Janeiro', '21831-480', 19, '$2b$10$E7wlyFwk4VqrFG3pbg91oeOmfyXXQWTLP.c.AmD1Cn/O3Mmxu.OGK', 'Assistente Social(Facilidade para falar em público)', 'A minha motivação é, poder está junto da comunidade realizando um trabalho de concientização e valorização da VIDA desda concepção.(dentro de uma perspectiva de que houve  uma banalização e um desrespeito à VIDA de uma forma geral).', 'Este é um projeto que não só valoriza a VIDA, como nos leva a refletir a importancia de não  pre- julgar o outro. Pois, a historia de cada individuo, começa desda concepção. Levando- nos a observar que particularidade existente no interor de cada um, muitas vezes é reflexo do seu comportamento.( timidez, imaturidade, agrecividade, apatia etc.)', NULL, NULL, '2026-06-28 22:38:58', 0, 'Ativo', '2024-01-08 10:20:19', NULL, 2);
