INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (882, 57, 'Maria Neuma Girão Rodrigues', 'Maria Rodrigues', 'Feminino', 'giraoneuma@gmail.com', '(88)999024756', 'Outro', 161, '1961-10-30 00:00:00', 'Rua Luiz Maia Sobrinho, 156', 'Morada Nova', '62940000', 6, '$2b$10$GVt6bAv37uB.NWaZjdX3K.HjuDQt/mJxohJAB43iPyxOk8Ai9bQPu', 'Ministra da Sagrada Comunhão,  Catequista,  RCC , Pastoral Familiar e ECC', 'Tive um aborto espontânea, sou a favor da vida desde a sua concepção,  com a graça de Deus conseguir conscientizar duas mães a não abortar suas crianças. Já rezo pelas crianças que correm risco de suas mães abortar. E uma criança a mãe fez o aborto mesmo eu conversando com ela a muitos anos atrás, e isso ainda doi em meu coração.  Quero defender a vida!', 'Quero contribuir com minha oração e minha voz para defender a vida.', NULL, NULL, '2026-06-28 22:39:06', 0, 'Ativo', '2024-05-25 22:48:10', NULL, 2);
