INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (902, 78, 'Elisangela Passos de Oliveira do Nascimento', 'Elisangela Nascimento', 'Feminino', 'elispon9@gmail.com', '(21) 99314-4524', 'Outro', 8, '1976-08-09 00:00:00', 'Rua Marechal Bibiano Costalat, 522 - Realengo', 'Rio de Janeiro', '21735-350', 19, '$2b$10$/EUA49zwcexvLQsH4DVQi.NVLx4wzHu1PyNGSdRDcSMFPupTD083m', 'Se precisar, posso falar em público.', 'Em primeiro lugar, por ser uma adoção de amor, experiência que traz muita gratidão ao meu coração, pois não conseguimos gerar filhos. E saber que pelo poder da oração podemos ajudar a salvar vidas, é muito gratificante!', 'O que me motivou também foi a possibilidade de divulgar a Adoção Espiritual dentro da realidade em que já estou inserida. E não necessariamente acrescentar outros compromissos, pois já sirvo na Paróquia, no Vicariato...', NULL, NULL, '2026-06-28 22:39:11', 0, 'Ativo', '2024-10-24 13:18:17', '2026-07-01 20:20:03', 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (903, 79, 'Fábio lixa do Nascimento', 'Fábio Nascimento', 'Masculino', 'fabiolixa@hotmail.com', '21973964653', 'Outro', 8, '1974-12-29 00:00:00', 'Rua Marechal Bibiano Costalat 522 Realengo', 'Rio de Janeiro', '21735350', 19, '$2b$10$vj/2X13UvB9hgKnwxc51c.93TEEoFXnRWQyNF/d5olh55a/8oHt2a', '', 'Dom Tiago olhar pra mim e me perguntar se eu daria um sim pra essa missão. Agora eu tô aqui', '', NULL, NULL, '2026-06-28 22:39:12', 0, 'Ativo', '2024-10-24 20:09:38', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (904, 80, 'Maria de Fatima dos Santos Valadares', 'Maria Valadares', 'Feminino', 'fatimavaladares@gmail.com', '85988837778', 'Outro', 88, '1954-09-18 00:00:00', 'Rua Queirós Ribeiro, 29', 'Fortaleza', '60410294', 6, '$2b$10$cOEIGqPQMs3ECQENa1Ew/uAafvc4iJcPrw2MAKKd7kos4qjQEQqHW', 'O que Deus permitir. Mas farei com amor, mas sou Pedagoga. Não tenho muito habilidade com redes sócias, apenas o básico. Falar em público me dá medo  mas se for preciso enfrento! Estou a disposição', 'Devido ter sofrido abortos tanto provocado, quanto natural, e fiz um Juramento a Deus que dali em diante faria tudo para ajudar as mães que precisem de mim. Meu último filho se Chama Emanuel,  pois foi promessa a Deus, e o consagrei no meu ventre a Ele.', 'Espero ajudar!', NULL, NULL, '2026-06-28 22:39:12', 0, 'Ativo', '2024-10-26 09:41:09', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (905, 81, 'Lúcia de Fátima de Lima', 'Lúcia Lima', 'Feminino', 'lucialimapedagogia@gmail.com', '(88) 992391691', 'Outro', 162, '2024-10-06 00:00:00', 'Rua 15 de Novembro 448 - Centro', 'Palhano', '62.910 000', 6, '$2b$10$EnoSI5xPT8pymGxkOGGTkeeOZbrChqBdESEmwMX18JEBPB/cwwPCm', 'Formação em pedagogia, tenho conhecimento nas redes sociais Instagram Lúcia Lima,  Facebook Lúcia de Fátima de Lima Lima, faço parte do grupo de liturgia e do grupo de música de minha paróquia, sou do grupo JOSEFINAS', 'Por ser fortemente a favor da vida, desejo de fazer algo a favor dos nascituros que correm o risco de serem abortados', 'Sou apaixonada por criança e gostaria muito de ter gerado filho, também o fato de ser mãe de dois filhos espirituais e orando pelo terceiro preenche um pouco o vazio, e como já mencionei sou a favor da vida. Assim sendo precisamos fazer algo todos os dias a favor dessa causa.', NULL, NULL, '2026-06-28 22:39:12', 0, 'Ativo', '2024-10-28 13:06:29', NULL, 2);
