INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (953, 129, 'Elaine Resende Furlan', 'Elaine Furlan', 'Feminino', 'elainerfurlan@gmail.com', '11988340058', 'Outro', 120, '2025-01-01 00:00:00', '12 Rua Sebastião Gil,12 - apto. 52 - Pinheiros', 'São Paulo', '05421-050', 25, '$2b$10$0438oDJlpA.SbOJv.EmqO.4r/Bwc4ItO0y67P5EegVbzE5rywVm/2', 'Gosto de ensinar catequese para crianças e adultos, auxiliar na liturgia.\r\n Tenho facilidade de falar em público, rezar o Santo Terço.', 'Há algum tempo estou em um grupo pró-vida, mas queria fazer algo mais concreto. Cada vez mais, vão abusado da lei e judiando das adolescentes, obrigando-as a abortar, parindo filhos mortos. \r\nNossa Senhora falou ao padre Gobbi pra formarmos seu exército, rezarmos o Terço e ela realizará os desígnios de Deus,  com o triunfodo seu Imaculado Coração.', 'Sou também catequista nas paróquias: Nossa Senhora do Perpétuo Socorro do Jardim Paulistano, com pároco padre Eduardo Ribeiro; Nossa Senhora Aparecida na Vila Beatriz, com pároco padre José Edson de Santana Barreto; São Pedro e São Paulo no Morumbi, com pároco padre Antônio C. Torres (diocese do Campo Limpo). As 2 últimas com a Catequese Bom Pastor.\r\nNa Paróquia Nossa Senhora do Monte Serrate colaboro com a liturgia. \r\nO ano do meu nascimento é 1967 (teria que voltar tudo isso mês a mês).', NULL, NULL, '2026-06-28 22:39:23', 0, 'Ativo', '2025-06-10 10:28:13', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (954, 130, 'Rosineide Barbosa Dos Santos', 'Rosineide Santos', 'Masculino', 'rosineide.arw@gmail.com', '75 )991838636', 'Outro', 196, '1965-09-08 00:00:00', 'Avenida sete de setembro \r\nNúmero 258 \r\nBairro Centro', 'Araci', '48760000', 5, '$2b$10$CV.KLjZ/6wchld5yWx3Eu.0lBGeVjboRlXYutEMxpoq6P8M0T3xJa', 'Conheço um pouco das redes sociais,falo em público muito pouco na capela que faço a Celebração da Palavra', 'Que muitos conheçam essa Missão tão sublime de Salvar vidas inocentes', 'Não sei se ficou claro as minhas respostas \r\nEstou a disposição pra qualquer dúvida.', NULL, NULL, '2026-06-28 22:39:24', 0, 'Ativo', '2025-06-10 21:43:31', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (955, 131, 'Gilcemara da Silva viana', 'Gilcemara viana', 'Feminino', 'gilcemaraviana@gmail.com', '21 96599-7975', 'Outro', 28, '1974-10-12 00:00:00', 'Avenida padre Guilherme decaminada, 2026, apartamento 402, bloco 4 Santa Cruz', 'Rio de Janeiro', '23575-000', 19, '$2b$10$KSUfbMqZry51JW1/J9dgP.FMv9sn1vhU4mb6AVRjj4qv1ATzk5PSO', 'Sou tímida preciso melhorar nisso.', 'Querer fazer algo por meus irmãos, pelo meu próximo, ser mais caridosa, piedosa e como trabalho muito, não consigo fazer parte de uma pastoral. Então acredito que Deus me colocou aquí por esse motivo.', 'Eu quero ajudar de alguma forma nesse trabalho lindo, já estou participando do Terço do Nascituro na minha paróquia com o grupo que já existe. Obrigada por tudo. Deus abençoe e Maria cubra com Seu Manto Sagrado.', NULL, NULL, '2026-06-28 22:39:24', 0, 'Ativo', '2025-06-11 10:06:09', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (956, 132, 'Osmarina araujo de sousa', 'Osmarina sousa', 'Feminino', 'mariaraujo2905@gmail.com', '(85)94115695', 'Outro', 156, '1978-05-29 00:00:00', 'Povoado Laura Muquem', 'Tejucuoca', '62610-000', 6, '$2b$10$WdmfXv3DpChNl2WwB4xkFuwScsU4YQhDxlyAu5/mAXLQ3hSSU6pVi', 'Eu sou catequista e ministra da sagrada comunhão e tenho facilidade em falar em público.', 'Já rezava pelas crianças que correm o risco de serem abortadas com Instituto Hesed e tinha vontade de conhecer mas esse projeto tão lindo.', 'Como eu já faço parte de pastorais falarei desse dessa missão assim que tiver algum material em mãos.', NULL, NULL, '2026-06-28 22:39:24', 0, 'Ativo', '2025-06-11 13:50:56', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (957, 133, 'Geani Alves dos Santos Oliveira', 'Geani Oliveira', 'Feminino', 'alvesgeani98@gmail.com', '(63)98423-6208', 'Outro', 144, '1977-07-20 00:00:00', 'Rua Princesa Isabel, 179', 'Paraíso do Tocantins', '77600000', 19, '$2b$10$ErSBw827IwRbydn5BYCTEeQnSVcrbpzEKZKrk3cLhycb7Khg/Dhjm', 'Boa vontade, gosto de trabalhar em equipe e trabalhos manuais.', 'O desejo de servir, ajudar o próximo e por considerar uma causa primordial de grande importância e necessária na qual Deus quer contar conosco para transformar e salvar vidas, iniciando por nós mesmo.', '', NULL, NULL, '2026-06-28 22:39:24', 0, 'Ativo', '2025-06-11 22:08:39', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (958, 134, 'Cristiane Fernandes Gorgulho', 'Cristiane Gorgulho', 'Masculino', 'crisgorg@gmail.com', '21981199592', 'Outro', 51, '1968-02-03 00:00:00', 'Rua General Mariante, 88 / 701', 'Rio de Janeiro', '22221-100', 19, '$2b$10$Ac.ALg9oq9Qrlno44fj5uue6nCyoHTWEpd8kNh/M4ajazRfhbGVeC', 'Não sei exatamente como eu poderia ajudar. Mas não tenho dificuldades para falar.', 'Eu já rezava a oração da Adoção Espiritual, quando fui convidada para o Treinamento. Mas confesso que eu não sabia que seria também para ser um divulgador desta causa. Achei que seria um treinamento para fazer a Adoção Espiritual da maneira correta, para me aperfeiçoar.', 'Eu trabalho durante o dia. Não sou aposentada não.', NULL, NULL, '2026-06-28 22:39:24', 0, 'Ativo', '2025-06-11 23:19:22', NULL, 2);
