INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (964, 140, 'Deuzenir Oliveira', 'Deuzenir Oliveira', 'Masculino', 'deuzenirlimoeiro@gmail.com', '(88) 99943-9173', 'Outro', 162, '1979-07-13 00:00:00', 'Rua Inácio Mendes, 2342 Centro', 'Limoeiro do Norte', '62930000', 6, '$2b$10$crhBZMy0ZdIu69hw064JuOLS8rxbGgQncAxM0l/lAp6BA/cGebXI6', 'Me comunicar com as pessoas.', 'O convite do Cleyton e um pouco do conhecimento sobre o movimento.', 'A Família Adoção Espiritual é um movimento muito interessante pois pela fé temos a certeza de que nossas orações estão salvando vidas, eu creio.', NULL, NULL, '2026-06-28 22:39:26', 0, 'Ativo', '2025-08-11 08:50:43', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (965, 141, 'José Nilton Mota', 'José Mota', 'Masculino', 'jninfo@bol.com.br', '63984027172', 'Outro', 144, '1969-10-17 00:00:00', 'Rua Tiradentes, 925 - Jardim Paulista', 'Paraíso do Tocantins', '77600-000', 19, '$2b$10$k4BFE3VZNAiuhXamDQFyUOmrZF.JFlkQaDadT7zHovgQCeBLaKcWK', '', 'Levar as crianças do meu ministério a ter consciência da necessidade rezar por outras crianças que estão em situação de vulnerabilidade', '', NULL, NULL, '2026-06-28 22:39:26', 0, 'Ativo', '2025-06-17 08:37:06', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (966, 142, 'Jéssica Celina farnezi Fernandes', 'Jéssica Fernandes', 'Feminino', 'materfecunda@gmail.com', '21982810399', 'Outro', 28, '1988-11-19 00:00:00', 'Rua campestre, 108', 'Rio de Janeiro', '23585240', 19, '$2b$10$JkEb29kfeUHDOlIoXLYiJu6otUMJsUMuXUXS63xoRH7uGPmjvHV/K', 'Sou formada em Administração e atuo com experiência consolidada em análise de dados e mapeamento de áreas, especialmente em contextos estratégicos e sociais. Ao longo da minha trajetória, desenvolvi também habilidades em comunicação e organização de projetos, incluindo eventos e ações comunitárias.\r\n\r\nBuscando ampliar meu impacto social, finalizei uma especialização em Família, o que me habilita para o atendimento como terapeuta de família e orientadora familiar, com uma escuta sensível, acolhedora e fundamentada em valores cristãos.\r\n\r\nAlém disso, sou especialista em Mariologia, o que me permite desenvolver reflexões, formações e palestras sobre o papel de Maria na espiritualidade cristã, com aprofundamento teológico e pastoral.\r\n\r\nComunicativa, não tenho dificuldades para falar em público e frequentemente participo de palestras, eventos religiosos e ações comunitárias, integrando formação, espiritualidade e ação prática.', 'Desde que devolvi um bebê para Deus ainda nos primeiros meses de sua gestação, meu olhar sobre as questões do aborto mudou profundamente. Foi uma dor transformadora, que me abriu o coração para acolher outras vidas — mesmo que de forma espiritual.\r\nQuando tomei conhecimento da adoção espiritual, seu propósito me tocou profundamente. Sempre desejei me tornar uma mãe espiritual, mas, na época, não compreendi bem o funcionamento do aplicativo e, infelizmente, acabei deixando a ideia de lado.\r\nHoje, ao integrar a Comissão em Defesa da Vida, sinto que essa chama se reacendeu. Encontrei um meio não apenas de me unir a outras mães espirituais, mas também de propagar esse lindo e necessário trabalho de intercessão pelas vidas que ainda estão por nascer.', '', NULL, NULL, '2026-06-28 22:39:26', 0, 'Ativo', '2025-07-21 18:26:03', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (967, 143, 'Solange Nascimento da Costa', 'Solange Costa', 'Masculino', 'solangecosta87@gmail.com', '(21) 989934599', 'Outro', 32, '2025-02-24 00:00:00', 'Rua Itaquê 463. Casa 1', 'Rio de Janeiro', '23094350', 19, '$2b$10$beC48aJgQcan1SLPBdy6deeiC7uDOnGAd7fs2LMuEts4DphO5ip1K', 'Não tenho conhecimento', 'Foi através do Rosário no Instituto Hesed quê D. Tiago participou e falou sobre Adoção espiritual, é quando eu conheci Débora na Catedral Metropolitana do Rio de Janeiro eu pedi a ela que reza se por minha filha quê tem endrometriose é deseja ser mãe. Eu confio no milagre na vida dá minha filha Andreza', 'Não tenho perguntas para fazer', NULL, NULL, '2026-06-28 22:39:27', 0, 'Ativo', '2025-07-21 19:51:37', NULL, 2);
