INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (985, 174, 'Angelita Pereira Dopazo', 'Angelita Dopazo', 'Feminino', 'angelmix0@gmail.com', '22998984189', 'Outro', 103, '1979-07-01 00:00:00', 'Rua Carolina, 55, Iguaba Pequena', 'Iguaba Grande', '28960000', 19, '$2b$10$TN8Y00G1S519Iaeej3uPaODMipHIN/.pNkE0PtJht0Pb5lupMplIS', 'Apesar de eu ser tímida, estou sempre fazendo palestra sobre paternidade responsável e o MOB no EPVM das paróquias da minha região.', 'O que me chamou a atenção foi a palavra adoção, mas depois entendi o propósito da adoção espiritual achei maravilhoso e resolvi ser um dos colaboradores da causa .', 'Espero ter tempo para tudo, pois sou agente da pastoral familiar de minha paróquia, instrutora e palestrante do MOB e coordeno as palestras dos instrutores do MOB da região dos Lagos - RJ.', NULL, NULL, '2026-06-28 22:39:31', 0, 'Ativo', '2025-09-26 11:15:30', NULL, 2);
