INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (987, 176, 'Alicia Castro', 'Alicia Castro', 'Feminino', 'aliciacmdcastro@gmail.com', '(21) 996066343', 'Outro', 4, '2005-04-09 00:00:00', 'Avenida Luiz Aranha 820 - apartamento 2005', 'Rio de Janeiro', '22793810', 19, '$2b$10$cYzkLIWA88CbIjuw3gRbvufO5r3IooCuu4OyforU68A4TRrr3hvHm', 'Área do Marketing e Redes Sociais. Edição de vídeos, cortes de podcasts, vídeos, gravações de palestras e produção de vídeo (do Dom Tiago Stanislaw, por exemplo) criação de conteúdo, divulgação de posts, panfletos, publicação e divulgação de conteúdos, etc.', 'Eu admiro muito o projeto lindo da Adoção Espiritual e o Dom Tiago Stanislaw. Uma das minhas missões de vida é ajudar a salvar vidas do aborto. Sempre fui uma jovem muito pró-vida e engajada nesse movimento em defesa da vida. Participo do grupo de formação pró-vida da minha paróquia, sempre vou em eventos pró-vida, como caminhadas, palestrasfaço divulgação de posts e vídeos nas minhas redes sociais, converso com algumas mulheres que correm risco de aborto nas redes sociais e ajudo algumas instituições pró-vida.', 'Adorei participar da formação e espero contribuir para esse projeto tão lindo.', NULL, NULL, '2026-06-28 22:39:31', 0, 'Ativo', '2025-09-26 11:28:19', NULL, 2);
