INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1066, 259, 'Angela Aparecida da Silva Menezes', 'Angela Menezes', 'Feminino', 'angela.menezes@comunidadecancaonova.com', '12997530911', 'Outro', 177, '1973-12-03 00:00:00', 'Rua Rio de Janeiro 80 Jardim da Fonte', 'Cachoeira Paulista', '12630-000', 25, '$2b$10$BYsGGlLKdbAbkMjMYh9edOa5fx3362Gmrhq3ge3ebsSl3ScPvf4mW', 'Formação em Rádio e TV, Gestão de Mídias Sociais, Gestão Pública, Curso Técnico em Edição de áudio visual, Aprofundamento em exorcismo para leigos, Teologia para Leigos, Marketing institucional religioso, Turismo Religioso, Comunicação. Dou cursos para mulheres, formação para novas comunidades, encontro de casais, famílias, encontro de jovens, encontro Mariano, encontro de cura e libertação. Sou escritora fantasma, roteirista do Programa Cantinho da Criança e dos conteúdos infanto juvenis do Sistema Canção Nova de Comunicação. Tenho especialização em MAM - Software para transmissão de Televisão em HD.', 'Desde 1992 eu rezo todos os dias por todos os bebês que estão no ventre de suas mães correndo o risco de perderem a vida e rezo para que o Espírito Santo toque no coração destas mãezinhas assim como fez comigo (eu ouvi o coração do meu filho batendo enquanto eu estava sendo preparada para cometer o assassinato, dentro de uma clínica de aborto e tenho absoluta certeza que foi o Espírito Santo quem tocou em minha alma para que eu mudasse a minha história). Mas mesmo estando aqui na Canção Nova há 26 anos, mesmo estando bem envolvido com grupos pró vida e instituições como a Casa Guadalupe, eu nunca ouvi falar da Adoção Espiritual. Em outubro de 2025 fui convidada a participar do Simpósio Duas Vidas em Nova Iguaçu Rio de Janeiro e lá, um casal me apresentou. Eu fiquei tão encantado com tudo o que eles me falaram que eu não perguntei o nome deles, peguei o cartãozinho e já anotei a data do meu primeiro filho espiritual direcionado que foi gestado no dia 05 de outubro de 2025, baixei o aplicativo que é bem intuitivo e naquele mesmo dia comecei à fazer as orações diárias conforme o APP. Providencialmente semanas depois a Isabel que é colaboradora foi rezar o terço do Nascituro que eu rezo todos os sábados 18h na Ermida da Mãe Rainha e é transmitido pelo YouTube Eventos Canção Nova. Assim que ela se apresentou me falou do curso que imediatamente eu me inscrevi. Eu digo que Deus me colocou na adoção Espiritual desde 1992, mas que só agora eu descobri.', 'Quero deixar registrado aqui A importância das partilhas durante o curso. Elas são de fato, uma formação à parte, um completo substancial que nos edifica. Cada um com suas lutas pessoais na família, na Paróquia, no trabalho. Eu toquei concretamente na "santidade do ordinário da vida" que o Papa Francisco escreveu em seu documento. Pude tocar na santidade que habita na alma dos mais simples e vi o quanto me preocupo com coisas poucas. Eu faria esse curso uma vez por mês só pra eu me converter mais.... \r\nEnfim, a adoção espiritual corresponde perfeitamente aos anseios da minha alma e por isso eu glorifico à Deus por ter me permitido chegar até vocês! Deus seja louvado pela inspiração e ousadia de Dom Tiago ter trazido para o Brasil. Deus seja louvado pelo destemor da Débora em abraçar esta causa. Deus seja louvado por cada colaborador que entende e abraça esta causa. SOMOS SALVA VIDAS EM MEIO À ESTE MUNDO DE TORMENTAS, por que assim Nosso Senhor quis. Contem comigo sempre. EIS ME AQUI.', NULL, NULL, '2026-06-28 22:39:50', 0, 'Ativo', '2025-12-02 09:39:17', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1067, 261, 'Simone de Freitas Carvalho Siqueira', 'Simone Siqueira', 'Masculino', 'scsiqueira28@gmail.com', '21985584699', 'Outro', 102, '1972-12-28 00:00:00', 'AV: Joaquim de Oliveira 1506, lote :544 Boa Vista', 'São Gonçalo', '24466-142', 19, '$2b$10$CoL8Ki20rxwiuBONJUdQWuOyq07kwEQhtCybz0Nqj62l4E5SrOATu', 'Vamos descobrir juntos! Mas ajudar na divulgação do projeto , acho interessante.', 'O projeto em si, e que me ajudou e também ajudará outras pessoas a ser mais orantes, aumentar também a nossa espiritualidade, e também por ser um projeto pró vida no qual sempre me interessei, e ainda não participava de nada que envolvia essa questão.', '', NULL, NULL, '2026-06-28 22:39:50', 0, 'Ativo', '2025-12-02 09:52:02', NULL, 2);
