INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1070, 264, 'Uslla Martins Furtado', 'Uslla Furtado', 'Feminino', 'uslla.mfurtado@gmail.com', '64999418019', 'Outro', 159, '1979-11-19 00:00:00', 'RUA JOÃO Luís de Moraes Qd 42 LT 04 Setor Cruvinel', 'Mineiros', '75834135', 9, '$2b$10$FkOAWwa/Ax5k9N18TAdNDe.P5RoD1bZtmC/b.PL9M1KSUkUivLAg.', 'Criação de artes, boa comunicação, facilidade para narrações e falar em público.', 'Desejo de conscientizar as pessoas para a abertura à vida', 'Sou grata a Deus por poder contribuir de alguma maneira a esse projeto do Sagrado Coração de Jesus, Imaculado Coração de Maria e Castíssimo Coração de São José!', NULL, NULL, '2026-06-28 22:39:51', 0, 'Ativo', '2025-12-02 14:52:01', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1071, 265, 'Lucivânia De Sousa Nunes', 'Lucivânia Nunes', 'Feminino', 'lucivanialuzia2018@gmail.com', '(64)999534782 / (64)', 'Outro', 160, '1966-01-26 00:00:00', 'Rua José de Alencar Qd 39b LT 11 Bairro Nossa Senhora Aparecida', 'Mineiros', '75836-682', 9, '$2b$10$YpId4r/jt9.kbq0mcVPuOe74ATka5JcHqTVkIH72qWVqv9ZFqUnJq', 'Facilidade para falar em público', 'O amor para com o bebê, os pais e familiares,e principalmente o amor a Deus.', 'Foi muito pouco tempo para ter um conhecimento melhor, porém,nesse tempo foi suficiente para a gente sentir esse amor e disponibilizar para ajudar ao próximo, principalmente as crianças no ventre da mãe correndo o risco de ser abortado e poder se defender. Aí que entra nós em defesa da vida. E também ganhar almas para Deus pela conversão dos pais da criança e os familiares.', NULL, NULL, '2026-06-28 22:39:51', 0, 'Ativo', '2025-12-02 15:25:49', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1072, 266, 'Lucas de Queirós Cavalcante', 'Lucas Cavalcante', 'Masculino', 'lucasqpsico@gmail.com', '(88) 99810-5901', 'Outro', 187, '2001-07-17 00:00:00', 'Avenida Sebastião Dantas N°180', 'Jaguaribara', '6349000', 6, '$2b$10$/KxWR/bOQDtM.3FX1Q3zu.q1BeQTU6WV9tMw5aTYjoPhnBFtNo2AC', 'Por ser psicólogo desenvolvo atividades de escuta e facilidade em fala com o público, além de lidar com redes sociais e fotografia.', 'Muito mais por algo pessoal, chamado e missão no qual foi resposta de orações.', 'Estou muito feliz em fazer parte deste projeto, tão lindo e encantador, espero conseguir colaborar de acordo com os desígnios de Jesus.', NULL, NULL, '2026-06-28 22:39:51', 0, 'Ativo', '2025-12-02 15:31:29', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1073, 267, 'Maria Eliene de Abreu', 'Maria Abreu', 'Feminino', 'eliene_abreu@hotmail.com', '859991363451', 'Outro', 86, '1973-08-10 00:00:00', 'Rua Bárbara de Dousa Costa, 103 casa A Lagoa Redonda', 'Fortaleza', '60831083', 6, '$2b$10$l6cSBNZ2EcMXhDUCjjIgP.3HXW3vao2vEUhKIQwGwkoEbORXMIlqq', '', 'Ser intercessor por um ser indefeso.', '', NULL, NULL, '2026-06-28 22:39:52', 0, 'Ativo', '2025-12-02 16:05:44', NULL, 2);
