INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1075, 269, 'Tania Raula Eletherio', 'Tania Eletherio', 'Feminino', 'taniaraulaeletherio@gmail.com', '21993632421', 'Outro', 102, '1950-10-26 00:00:00', 'Rua Zulmira', 'São Gonçalo', '24440090', 19, '$2b$10$hTSihtCgNrupcOj4HeTdSuBLSN1cO2.bCR7coLS35zpqUPQjTESdy', 'Facilidade em comunicação', 'Minha mãe tentou me abortar até os 6 meses de gestação.\r\nPor isso rezo por aqueles q estão na mesma situação', 'A adoção espiritual é um gesto de amor e desapego, não é meu,todos são progetos de Deus.', NULL, NULL, '2026-06-28 22:39:52', 0, 'Ativo', '2025-12-02 17:46:54', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1076, 270, 'Maria Irani araujo de sousa', 'Maria sousa', 'Feminino', 'mariairani683@gmail.com', '85991809571', 'Outro', 156, '1980-03-28 00:00:00', 'Localidade Laura Muquém Tejuçuoca Ceará', 'Tejucuoca', '62610000', 6, '$2b$10$fzraAIf173eV0XKPswJ6p.lG10B7/HcNT03Qqws9A7jUhMQQB7UQa', 'Trabalho na área da saúde onde encontro mulheres que tomam anticoncepcional e falam em não ter mais filhos posso aconselhar', 'Ajuda criança a vir au mundo é minha maior alegria com minhas orações', '', NULL, NULL, '2026-06-28 22:39:53', 0, 'Ativo', '2025-12-02 18:16:38', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1077, 271, 'Jaqueline Costa Pereira Pacheco', 'Jaqueline Pacheco', 'Masculino', 'jaquecostaper@gmail.com', '21985342290', 'Outro', 105, '1968-02-17 00:00:00', 'Rua Ivan Bragança n78', 'São Gonçalo', '24420-640', 19, '$2b$10$33gEEa9IuqdC3P/MqQaqceNZoAKhw1C0ZdK20vBLulj1aRGGSPCWe', 'Nessa área nada. Gosto de trabalhar na cozinha.', 'Fui na canção Nova em Outubro e rezei o terço com a Angela e conheci o projeto e gostei', 'Estou muito realizada em participar pois ja tive uma experiência participativa com essa situação, hoje vendo o vídeo da Dane me recordei que nem sempre um aborto e espontâneo e sim obrigado mas no futuro conto esse testemunho.', NULL, NULL, '2026-06-28 22:39:53', 0, 'Ativo', '2025-12-02 18:53:31', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1078, 272, 'Gerliana Mendes de Sousa', 'Gerliana Sousa', 'Feminino', 'gerlianamk@outlook.com', '88999117285', 'Outro', 186, '1977-10-24 00:00:00', 'Rua Manuel Sabino Mendes -2160', 'Flores Russas', '62908500', 6, '$2b$10$BUqT1TDjU93zkMPYGi/ZdOnqGtNkEtu/ENZc8rS.MKeyiH4SPnbhS', 'Sem muito talento, irei orar e divulgar em minha paróquia.', 'Salvar vidas indefesas', 'Sou tímida, mas a cada dia o espírito Santo me ajuda, espero que eu posso colaborar com oração e divulgação do movimento.', NULL, NULL, '2026-06-28 22:39:53', 0, 'Ativo', '2025-12-02 20:09:23', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1079, 273, 'Rebeca Maria Nogueira Peixoto', 'Rebeca Peixoto', 'Feminino', 'rebecamarianogueira04@gmail.com', '(88) 9 9940-0108', 'Outro', 187, '1999-12-04 00:00:00', 'Rua Francisco Rofson Bezerra do Ceara', 'Jaguaribara', '63490-000', 6, '$2b$10$B5ov2P6BfJ1PZKfQUD5OJuyqbO7pVJPNfC7eHFRRR3IXpCCWTf8pu', '', 'Salvar a vida de bebês e mães', '', NULL, NULL, '2026-06-28 22:39:54', 0, 'Ativo', '2025-12-02 20:17:37', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1080, 274, 'Fátima Almeida', 'Fátima Almeida', 'Feminino', 'fatima.almeidaj@hotmail.com', '21 989998537', 'Outro', 6, '1961-02-19 00:00:00', 'Rua Albino Paiva 644 casa 103 Senador Camará - Bangu Obs.: Endereço provisório casa em processo de v', 'Rio de Janeiro', '21830-490', 19, '$2b$10$CcWzsE8sg9Wl91q24HiZTO9NmMqe3J8riGYuoqyFWdA528FxW7tWi', 'Já fui voluntária na recepção de peregrinos, e pessoas em situação de vulnerabilidade. Fiz parte do Coro no Santuário Nossa Senhora de Fátima no Recreio dos Bandeirantes rj. \r\n\r\nPorém, muito me agrada a oração dos Terços: Mariano, da Misericórdia e das Mães que Oram pelos Filhos. Faço parte dos três.', 'O SIM, pela Vida. Colaborar para que a vida dos nascituros sejam preservadas.', 'Sinto no meu coração que terei um crescimento gradativo na missão da Adoção Espiritual, será passo a passo., porque tenho consciência do meu processo de cura. Mais uma vez, quero parabenizar e agradecer a todos envolvidos nesse projeto lindo e necessário de Amor a Vida. \r\n\r\nObs.: de Dezembro à Fevereiro estarei oscilando entre Bangu e Vargem pequena.\r\nInício de março até início de abril estarei em Fátima Portugal. Pode ser uma possibilidade da divulgação desse lindo Projeto por lá. Ou talvez já tenha colaboradores em Fátima.\r\nAbraço fraterno.', NULL, NULL, '2026-06-28 22:39:54', 0, 'Ativo', '2025-12-02 20:35:11', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1081, 275, 'Joyce Carla dos Santos', 'Joyce Santos', 'Masculino', 'joycerezende17@gmail.com', '31997661211', 'Outro', 70, '1976-08-02 00:00:00', 'Rua Arlindo José dos Santos 30 bairro Novo Horizonte', 'Betim', '32606018', 13, '$2b$10$GHJ37xZTph4u0OrMlrcinuP.tY7K.KxmT/d5HAm17jxetVf.szJH6', 'Facilidade para falar em público. Orações.', 'Adoção das minhas filhas, e o quanto é importante orar pelos bebês para não serem abortados.', '', NULL, NULL, '2026-06-28 22:39:54', 0, 'Ativo', '2025-12-02 22:22:48', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1082, 276, 'Arlineide nazare morais Vieira silva', 'Arlineide silva', 'Masculino', 'neidinha2227@gmail.com', '85986072495', 'Outro', 80, '1980-03-31 00:00:00', 'Rua cônego Mourão 200', 'Fortaleza', '60710080', 6, '$2b$10$WlhhzB5qV2k6hywvFpD9buZs3FLNOLmrx4PqDRIXD45lWN.RGnoCK', '', 'O amor e a oracao pela crisnça', '', NULL, NULL, '2026-06-28 22:39:54', 0, 'Ativo', '2025-12-02 22:45:30', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1083, 277, 'Altemar Aparecido Pichler', 'Altemar Pichler', 'Masculino', 'altemaraparecidopichler72@gmail.com', '(11)97065-3642', 'Outro', 201, '1972-04-09 00:00:00', 'Rua: Manoel Álvares Pimentel, n*1363', 'Jardim Miriam-Guaianazes', '08141-000', 25, '$2b$10$Iy7vvfCoFaMa0N9Cr9iO2eKjn/LyXXAMpBxOMGtg2eGQajsozJu4a', 'Graças a Deus e Nossa Senhora, eu tenho muita facilidade,em falar em público, porque, eu quase sempre leio, a primeira ou a segunda leitura e até o salmo, nas Santas Missas ou Santas Celebrações da Santa Palavra de Deus, sem falsa modéstia e sem querer, me exaltar, graças a Deus e Nossa Senhora, eles me deram o grande, lindo e maravilhoso Dom, de compor músicas religiosas e poemas, eu também ganhei de Deus e Nossa Senhora, o lindo e maravilhoso Dom de cantar, eu conduzo com alguns amigos, algumas orações e evangelizaçoes nas, casas e também eu consigo explicar a Santa Palavra de Deus e eu também conheço a vida de vários Santos e Santas e por fim, eu consigo levar alegria e paz, pelo menos em quase todos os lugares onde eu vou, porque, eu procuro ser bastante paciente e humilde, mas, infelizmente, nem sempre eu consigo ser assim,as, tudo acontece no tempo de Deus, kkkkk, não é mesmo?', 'O que realmente me conquistou e me levou a ser, um novo colaborador da Adoção Espiritual, foi, é e sempre será, o amor a Deus sobre todas as coisas e ao próximo como a mim mesmo, é por isso, que eu quero ser cada vez mais, um verdadeiro colaborador da Adoção Espiritual, para interceder e salvar, a vida de algumas criança, que infelizmente, estejam correndo o grande perigo, de serem abortadas, entenderam?', 'Quando eu conheci, esse lindo, maravilhoso, forte e emocionante, projeto, da Adoção Espiritual, eu me apaixonei a primeira vista, mas, infelizmente, eu não consegui ser perseverante, como eu deveria ser, mas, agora tendo acabado de ter participado da linda, maravilhosa, forte e emocionante formação, para nós sabermos o que é e para que serve um colaborador, na Adoção Espiritual, sendo assim, eu quero buscar em Cristo Jesus, Nossa Senhora, São José e nos irmãos, que se tornaram e que ainda irão,se tornar colaboradores da Adoção Espiritual, eu quero conseguir com a grande ajuda deles, a perseverança e o amor, necessários, para eu ser cada vez mais, um verdadeiro e perseverante, Pai Espiritual de uma criança que infelizmente, venha correr o grande risco de ser abortada, entenderam? Desde já, muito obrigado e fiquem com Deus e Nossa Senhora.Amem!!!!', NULL, NULL, '2026-06-28 22:39:55', 0, 'Ativo', '2025-12-03 00:42:30', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1084, 278, 'Iolanda', 'Iolanda', 'Feminino', 'iolandama60@gmail.com', '31980 257767', 'Outro', 74, '2025-12-03 00:00:00', 'Rua Gorceix, 387.', 'Betim', '32672-156', 13, '$2b$10$wqv6GXCYvALjbojb2qDH3u.Jo0omulV0Yzatiods5iLoEqTrNJ6x.', 'Facilidade para ensinar / professora de Língua portuguesa', 'Sempre ao rezar o mistério terço do nessa intenção com as irmãs do Instituto Hesed, me sentia tocada e sensibilizada com essa situação o que me levou em busca do conhecimento do projeto,mas antes mesmo dessa busca iniciar ,veio o convite para participar do treinamento através da Marta. Entendi então que, esse meu desejo também era o chamado de Deus para mim.', '', NULL, NULL, '2026-06-28 22:39:55', 0, 'Ativo', '2025-12-03 06:04:51', NULL, 2);
