INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1091, 285, 'Francisca Francilania Melo Jorge', 'Francisca Jorge', 'Feminino', 'franciscamelofmj@gmail.com', '19 981361594', 'Outro', 76, '1975-03-03 00:00:00', 'Rua Antônia Ribeiro de Lima, 26 Apto. 33 Bl Z - Cond. Pq da Mata II - Pq São Jorge', 'Campinas', '13064832', 25, '$2b$10$iZMiyIJUS/.k6zMqL2z6lu6u2WQWsncAnGc0QV1YzUPlHRsVK.S4O', 'Através do Terço que realizo no último Sábado de Cada mês, tenho adquirido confiança em falar em público, desenvolver, planejar e organizar eventos…', 'A ajudar as mulheres que cometeram aborto assim como eu, a se perdoarem. A buscar forças no nosso Deus. Porque, primeiro Deus nos perdoou e continuar rezando pelo os meus dois filhos que estão no Céu e rezar por aqueles que estão correndo o risco de serem mortos pelo o aborto.', 'Já agradeço a Deus por estar preenchendo esse formulário para fazer parte dessa família da Adoção Espiritual.', NULL, NULL, '2026-06-28 22:39:56', 0, 'Ativo', '2025-12-06 14:31:44', NULL, 2);
