INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1139, 333, 'Francisca Luciana Moreira Silveira', 'Francisca Silveira', 'Feminino', 'patrimonialluciana@gmail.com', '88993070295', 'Outro', 185, '1971-06-07 00:00:00', 'Tv. Rosebdo Correia Lemos 820 Centro', 'Jaguaruana', '62823000', 6, '$2b$10$xtCLnVxmYt8lwowKs5rgXO.YovO65DY8PybNNEK0wcJgTVSLooGjG', 'Tenho formação técnica em TI concluída e atualmente estou finalizando o curso de Análise e Desenvolvimento de Sistemas (ADS), com conclusão prevista para junho. Ao longo da minha formação, desenvolvi projetos de criação de sites, adquirindo experiência prática na área.\r\nTambém possuo conhecimentos em redes sociais(podendo aprender mais) e tenho facilidade em comunicação, especialmente para falar em público. Além disso, posso contribuir na criação de artes e conteúdos.\r\nConsidero como meu maior talento a vontade constante de aprender e evoluir, sempre buscando contribuir da melhor forma possível e ajudar no que for necessário.', 'O que me motivou a ser uma colaboradora paroquial da Adoção Espiritual é o desejo de ajudar as pessoas a desenvolverem mais amor ao próximo. Acredito que não é julgando que ensinamos, mas sim através da oração e do exemplo.\r\nVejo nesse projeto a força que a oração tem e o quanto ela pode transformar vidas, especialmente em um tempo tão difícil e conturbado como o que estamos vivendo. Entendo que ser um “pai” ou “mãe” espiritual vai além de rezar por uma criança, mas também envolve interceder por toda a família.\r\nMeu coração se enche de alegria ao poder fazer parte dessa missão, contribuindo para a disseminação do amor, da fé e da esperança.', 'Estou totalmente disponível para aprender e colaborar no que for necessário dentro do projeto. Tenho facilidade em trabalhar em equipe, boa comunicação e disposição para ajudar tanto nas atividades técnicas quanto nas ações pastorais.\r\nCaso necessário, posso contribuir com apoio na área de tecnologia, criação de conteú\r\ndos e também em atividades que envolvam comunicação com o público. Estou aberta  \r\na orientações e sempre disposta a crescer e servir da melhor forma possível.', NULL, NULL, '2026-06-28 22:40:08', 0, 'Ativo', '2026-03-21 18:46:34', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1140, 334, 'Maria Pérola Acker Sardinha', 'Maria Sardinha', 'Feminino', 'mperola@gmail.com', '21 99584-3730', 'Outro', 155, '1969-01-30 00:00:00', 'Av nações unidas 611 apt 105 - Muriqui', 'Mangaratiba', '28700000', 19, '$2b$10$84m088LqWFJaPc/Cq7K8bOoH6LXA7fmihVHUbc.1ZSROU1vo7zSJu', '', 'O.poder da oração para transformar a dor em amor e assim o aborto ser cada dia menor.', 'Q Deus me ajude a ser uma fonte de amor e luz pelas famílias', NULL, NULL, '2026-06-28 22:40:08', 0, 'Ativo', '2026-03-21 20:03:48', NULL, 2);
