INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1164, 358, 'Cintia da Silva de souza', 'Cintia souza', 'Feminino', 'dasilvadesouzacintia@gmail.com', '(21)970227783', 'Outro', 6, '1977-09-30 00:00:00', 'Rua projetada um casa A n 9 estrada de sepetiba Santa cruz', 'Rio de Janeiro', '23520-285', 19, '$2b$10$sPFBFp9Cmhr3RPSk7.b5vORzzQ4QVFYvkWLah2FANP/VJJzcp4/BG', '', 'Espero contribuir com o crescimento da pastoral ao qual fazemos parte e principalmente auxiliar nesse processo tão significativo que e o de rezar por uma criança...', '', NULL, NULL, '2026-06-28 22:40:13', 0, 'Ativo', '2026-03-27 10:52:21', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1165, 359, 'Adriana Fonseca', 'Adriana Fonseca', 'Feminino', 'artesdavoadri@gmail.com', '11 977859469', 'Outro', 135, '1973-01-01 00:00:00', 'R: Ricieri Dante Galhardoni, 144', 'Mogi mirim', '13843352', 25, '$2b$10$6W7tM6FEf7ExX0SM9L0/g.N7W./ZLOqh4cQHGbM3GT5Rd9Xfvc/3G', 'Facilidade de falar em público, sou formadora do grupo das mães que oram, sou artesã Facilidade com trabalhos manuais. Formatação de texto Word e ppt.', 'Convite do pároco, antes não conhecia o movimento.', 'Eu e meu esposo Marcos Fonseca, nos colocamos a disposição para colaborar com a Adoção Espiritual no que for necessário. 🙏🙏🙏', NULL, NULL, '2026-06-28 22:40:14', 0, 'Ativo', '2026-03-27 11:01:25', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1166, 360, 'Manuela Moura de Almeida', 'Manuela Almeida', 'Feminino', 'lelamoura@outlook.com', '85996210001', 'Outro', 89, '1989-12-17 00:00:00', 'Rua Dr. João de Deus, 645 - Fátima', 'Fortaleza', '60040-350', 6, '$2b$10$vbn78TuWw.fvMpJZSlqq7O3GS3Tj0qbvPECz3XrVo0DSiN5TuTzZi', 'Sou fotógrafa de família, tenho um certo conhecimento em redes sociais. Não sou uma oradora nata, mas estou acostumada a dar formações na comunidade que faço parte (Comunidade Obra Lumen - https://obralumen.com.br/ | instagram.com/obralumen | Instagram.com/lumenserfeliz). Sempre tive um chamado muito forte à intercessão. Tudo isso pra dizer que nesse primeiro momento ainda estou entendendo de que forma posso ajudar mais o movimento, acredito que depois da reunião com a coordenação local, fique mais claro. O fator tempo disponível é algo a ser levado em conta por já estar comprometida com outros movimentos/serviços/carismas.', 'Desde o ano passado eu comecei a me inquietar de servir na comunidade, e não contribuir com um serviço na paróquia. Existe de fato no meu coração uma sede de ser Igreja e de comunhão entre os carismas, serviços, movimentos. Encontrei na Adoção Espiritual a possibilidade de levar a causa pró-vida de uma forma espiritualizada e amorosa para dentro da paróquia. Pelo menos na minha cidade (Fortaleza), não se fala muito sobre o assunto, a não ser em tempo de eleições. O treinamento me deixou ainda mais encantada com a forma como o assunto é abordado no movimento: o foco na vida, o acolhimento da mulher, a intercessão simples e silenciosa pela criança e pela família, a possibilidade de trabalhar a afetividade e a sexualidade quando se aprofunda na maternidade e na paternidade espiritual. Meu objetivo é apresentar o movimento ao meu pároco, mas também à moderação da Obra Lumen, onde atualmente sou membro do setor de formação e espiritualidade.', 'Muito obrigada por todo zelo no treinamento, foi muito bom.', NULL, NULL, '2026-06-28 22:40:14', 0, 'Ativo', '2026-03-27 16:01:19', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1167, 361, 'Maria Márcia dos Santos Miranda', 'Maria Miranda', 'Feminino', 'mariamarcia.ss@gmail.com', '99988516049', 'Outro', 153, '1985-06-05 00:00:00', 'Rua Esmeralda, casa 06, Residencial Pôr do Sol, Bairro santa Inês.', 'Imperatriz', '65919468', 10, '$2b$10$PDWGtVfMvHXAiTKDE4zBvuGUi8o1U/kMDez3vcM2Zt1MsdWJQdKYq', 'Redes sociais', 'Recebi o convite e amei conhecer todo o trabalho.', '', NULL, NULL, '2026-06-28 22:40:14', 0, 'Ativo', '2026-03-27 19:36:20', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1168, 362, 'Regina Celi Landim Linard', 'Regina Linard', 'Feminino', 'reginaceli.linard@gmail.com', '88 997950594', 'Outro', 143, '1960-06-14 00:00:00', 'Avenida Dr. Raimundo Gonçalves de Lucena,320', 'Missão Velha', '63200000', 6, '$2b$10$o995b1CdwzoChweEYdzoYOq9d6LFs2ruemFw8xbHuXeGJWH8JZ78a', 'Meus talentos são os básicos, nas redes sociais; Como Professora na área educacional convivência e relacionamento é forte. Mas a sede de aprendizagem é uma janela aberta.', 'Primeiro o convite de uma amiga, junto com a curiosidade de conhecer melhor a obra. E a enorme necessidade de servir a Deus.', 'Apesar das minhas limitações,  no cuidado do meu esposo com Alzheimer, o engajamento nas Pastorais e Serviços da Igreja é terapêutico e me faz muito feliz. Além de me fortalecer na Fé.', NULL, NULL, '2026-06-28 22:40:14', 0, 'Ativo', '2026-03-27 20:25:15', NULL, 2);
