INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1196, 390, 'Joel Domingos da Silva', 'Joel Silva', 'Masculino', 'domingosjoeldsilva@hotmail.com', '21-987283193', 'Outro', 148, '1962-06-19 00:00:00', 'Rua Silva Jardim, N• 580 , Vila São Luiz', 'Duque de Caxias', '25065-143', 19, '$2b$10$KojlqwioviQjXjCaeMwJ8u3ws9lKpfG6y.WehIaDKQBXe0sUenKBS', 'Conhecimento de rede social', 'Pelo belo projeto em pró da vida', 'Os treinamentos foram de muita valia , eu consegui entender e vou partilhar com a minha comunidade.', NULL, NULL, '2026-06-28 22:40:21', 0, 'Ativo', '2026-05-09 10:38:29', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1197, 391, 'Edineia Ramos da Silva', 'Edineia Silva', 'Feminino', 'edineiaramosdasilva44@gmail.com', '21997182956', 'Outro', 52, '1972-05-13 00:00:00', 'Rua Uranos, 1281 apt 403', 'Rio de Janeiro', '21060-970', 19, '$2b$10$DS761YXftWD9bYw9whSYL.olKf7LblBEDzYIYx2UtM/c9v1ct5d8C', 'Tenho facilidade para falar com o publico, tenho um curso tecnico de Gestão de pessoas.', 'Faço parte do movimento pró-vida e do grupo de Mães que oram pelos filhos. O encontro com esses movimentos, e conhecendo como é a Adoção Espiritual me motivaram a ser um colaborador com amor.', 'Senti a necessidade de fazer algo por alguém, pois há 14 anos atrás, mais precisamente dia 31 de março de 2012, até a data que conheci o movimento de mães que oram pelos desde novembro 2021. E o movimento pró-vida desde a quaresma de 2026. E agora a Adoção Espriritual. Sinto novamente a alegria de amar o próximo e vontade de rezar.', NULL, NULL, '2026-06-28 22:40:21', 0, 'Ativo', '2026-05-09 11:10:24', NULL, 2);
