INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1200, 394, 'Larissa Fernanda Barreto Souza', 'Larissa Souza', 'Feminino', 'fernanda.souza.96@hotmail.com', '22992122638', 'Outro', 103, '1996-02-26 00:00:00', 'Rua Alcântara, lt 02, qd 03, Fazendinha', 'Araruama', '28984045', 19, '$2b$10$0HCJP3h9fmxkoDNEtgcf.ufyu.qrXteZGz91uk/nWpEQFrVRdLxBm', 'Eu tenho uma dificuldade horrorosa de falar em público, mas estou melhorando. Sou formada em Nutrição, estou cursando Administração e amo fazer crochê.', 'Primeiro foi por ser mãe. Em segundo foi a vontade de querer ajudar na Igreja de alguma forma que eu ainda não tinha conseguido.', '', NULL, NULL, '2026-06-28 22:40:22', 0, 'Ativo', '2026-05-09 12:56:49', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1201, 395, 'Jussara Fontes', 'Jussara Fontes', 'Feminino', 'jsa.fontes@gmail.com', '21 99116-6348', 'Outro', 131, '1964-08-23 00:00:00', 'Rua senador santos Rocha 90 Pita', 'São Gonçalo', '24417-020', 19, '$2b$10$UUtb8CueqTQWQJCqQX3ZW./q1Hb0DGtaGUrQEusQJftfuzub6sYQW', 'Técnica de enfermagem', 'Motivou a certeza de que cada vida é preciosa aos olhos de Deus e que minha pequena contribuição, unida à fé, pode gerar esperança, proteção e transformação. Ser colaborador é viver a caridade e a missão de cuidar da vida com amor e responsabilidade', 'Adoção Espiritual é um compromisso de oração em favor da vida, especialmente pelas crianças em gestação e suas mães, fortalecendo a cultura do amor e do cuidado.\r\nComo colaborador paroquial, é importante cultivar fidelidade na oração, testemunho de vida cristã e disponibilidade para incentivar outras pessoas a abraçarem essa missão.\r\nA participação exige perseverança, discrição e confiança na ação de Deus, reconhecendo que mesmo um gesto simples, como a oração diária, pode produzir grandes frutos espirituais.', NULL, NULL, '2026-06-28 22:40:22', 0, 'Ativo', '2026-05-09 20:08:03', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1202, 396, 'Giselle Aparecida Faria Costa', 'Giselle Costa', 'Masculino', 'gisafc08@gmail.com', '(21) 988797739', 'Outro', 16, '1969-12-08 00:00:00', 'Avenida Guilherme Maxwell 530 - c/07 - Bonsucesso- RJ', 'Rio de Janeiro', '21042110', 19, '$2b$10$Xdoqew3SaBIIZtnQQti3Pu2MJ94n88ejKbAbGlMlJXT6j9j1U.QHW', 'Facilidade para falar em público, toco violão, tenho facilidade com artes ( trabalhos manuais ) Sou professora ,formada em Pedagogia. Estou servindo na ICI e tambem MESC.Estou fazendo o curso para Pregadores da Palavra .\r\nVou começar o curso de Mattereclesiae', 'Eu trouxe o Movimento das Mães que oram pelos filhos para a Matriz em 2017. Em 2023, recebi o chamado de Deus por um convite de uma irmã do grupo para a adoção espiritual, e , começamos juntas a rezar.\r\nA atual coordenadora do grupo AMO postou o treinamento no WhatsApp e apenas eu e outra pessoa atendemos ao chamado. Deus quis assim. Eis- me aqui, Senhor!', 'Deus sabe o porque e o para que me escolheu para esta missão. Minha resposta é sim. Que Ele me capacite, me prepare, me fortaleça e me esconda Nele, para que somente Ele seja tudo em mim.', NULL, NULL, '2026-06-28 22:40:22', 0, 'Ativo', '2026-05-09 20:10:05', NULL, 2);
