INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1205, 399, 'Eleny Maria de Moraes nsc78', 'Eleny nsc78', 'Feminino', 'elenyiankaerika@gmail.com', '64999917752', 'Outro', 205, '2026-03-22 00:00:00', 'Rua Alcântara Vilela n70 setor alto paraíso', 'Doverlandia', '75855000', 9, '$2b$10$6fi82hcqsu8vFePfdIcN3OyUjRTlg6p0i04bLQBOGwI0D6Ru6spY2', '', 'Comecei a partir das reuniões de formação para novos colaborador e fui conhecendo melhor e gostei do movimento!!', 'Estou feliz por ser uma colaboradora e espero futuramente conseguir cada vez mais voluntários e pais adotivos!!', NULL, NULL, '2026-06-28 22:40:23', 0, 'Ativo', '2026-05-11 19:21:35', NULL, 2);
INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1206, 400, 'DEONICE RAFAEL DO NASCIMENTO ROCHA', 'DEONICE ROCHA', 'Masculino', 'deoniceseminario@hotmail.com', '64999710317', 'Outro', 159, '1981-06-04 00:00:00', 'RUA : SPA 19 QD: 13 LT: 14 SÃO PEDRO', 'MINEIROS', '75831314', 9, '$2b$10$phrpqKQhSSVslpdkZVvBfe1lr2iXm5gCS9gZVgIs3sfK1FFs7YGpu', 'Tenho facilidade em comunicação, organização e trabalho em equipe. Possuo experiência na área da educação, no acompanhamento de estudantes e no desenvolvimento de atividades pedagógicas. Também tenho facilidade para falar em público, acolher pessoas, auxiliar na organização de eventos e contribuir com ideias para projetos e ações sociais. Além disso, tenho interesse em colaborar na criação de conteúdos, mensagens e materiais de divulgação para fortalecer o trabalho da Adoção Espiritual.', 'O que me motivou a ser um colaborador paroquial da Adoção Espiritual foi o desejo de servir a Deus de forma mais próxima, contribuindo com uma missão que promove a vida, a oração e o cuidado espiritual.', '', NULL, NULL, '2026-06-28 22:40:23', 0, 'Ativo', '2026-05-11 20:24:07', NULL, 2);
