INSERT INTO `colaboradores` (`id_colaborador`, `cod_colaborador`, `nome_colaborador`, `apelido_colaborador`, `sexo`, `email`, `telefone`, `perfil`, `id_paroquia`, `data_nascimento`, `endereco`, `cidade`, `cep`, `id_estado`, `senha`, `talentos_colaborador`, `motivou_AE`, `obs_colaborador`, `foto_colaborador`, `selo_colaborador`, `dt_ultimo_acesso`, `qtd_acesso`, `status`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1219, 413, 'Sergio Messias Baptista', 'Sergio Baptista', 'Masculino', 'sergiomessiasbaptistaoficial@gmail.com', '11996060599', 'Outro', 118, '1969-12-02 00:00:00', 'Rua Dom Estevão Pimentel, 462 (Casa) Chacara Belenzinho SP CEP 03378-050', 'São Paulo', '03378-050', 25, '$2b$10$i2Wguk3xoG.ksnfp4PbuiecSabAhzQTK3nZkXXQLukmVZqYSLFdBe', 'Formação em Administração de Empresas com enfase em Comércio Exterior, Pós Graduação em Gestão Empresarial. Disponibilidade para continuar aprendendo cada vez mais, facilidade para detectar processo de melhorias, gestão , comunicação , controles, escrita , negócios , oratória e aproximar pessoas em equipe', 'além de ser católico de berço, filho de catequistas atuei na pastoral do batismo e no momento faço parte do movimento Terço dos Homens em várias paróquias e sou Vicentino pela Conferência da Nossa Senhora de Lourdes. Minha esposa também é catequista e durante uma preparação de 33 dias para se consagrar a São José na paróquia Santa Generosa (Paraiso) fomos convidados para adotar espiritualmente um bebê e começamos no dia 25 de março deste ano e isto me motivou a colaborar em defesa da Vida pois já participei e tive alguns contatos pró vida na marcha em São Paulo e no stand da Expocatólica alem de ser pai de 2 filhos e de 01 neto na qual entendo que a Familia sempre sera a base de formação da sociedade e comunidades católicas mediante o legado que recebi e pretendo repassar para outras gerações defendendo a vida desde a concepção até o declinio natural .', 'Entendo que O hábito de rezar o terço fortalece a fé e serve de exemplo para a família e a comunidade e no doação Vicentina o olhar para o Assistido ajuda e muito a desenvolver sensibilidade para ver o rosto de Cristo nos pobre, no doente e no excluido para que se promova e possa seguir em frente respeitando os valores familiares. Tenho um testemunho na familia que poderia ter evoluido para a interrupção de uma gestação mas graças ao bom Deus que nunca nos desamparou conseguimos perceber a existência de algo errado e conseguimos apoiar o nascimento mesmo sem a presença paterna. LSNSJC e sua Mãe Maria Santissima! Paz e bem !', NULL, NULL, '2026-06-28 22:40:26', 0, 'Ativo', '2026-05-14 23:54:37', NULL, 2);
