INSERT INTO `paroquias_historico_relacionamento` (`id_paroquia`, `data`, `canal`, `detalhes`, `id_colaborador_atualiza`, `data_inclusao`) VALUES (2, '2026-05-20 00:00:00', 'Reunião presencial', 'A coordenadora Meri tem buscado junto ao pároco Padre Julinho manter fixa equipe da Adoção Espiritual na paróquia. Ainda não houve retorno positivo do pároco.', 2, '2026-05-31 15:18:32');
INSERT INTO `paroquias_historico_relacionamento` (`id_paroquia`, `data`, `canal`, `detalhes`, `id_colaborador_atualiza`, `data_inclusao`) VALUES (2, '2026-08-22 00:00:00', 'Reunião presencial', 'Após a missa de 18h, e no dia do primeiro Aprofundamento da Adoção Espiritual, Silvia Juliasse falou com Padre Julinho que a Adoção Espiritual precisa muito da ajuda liberando um dia no mês para terço da Adoção Antes da missa. Padre Julinho informou que era só marcar o dia e informar na secretaria.', 2, '2026-09-17 14:07:01');
INSERT INTO `paroquias_historico_relacionamento` (`id_paroquia`, `data`, `canal`, `detalhes`, `id_colaborador_atualiza`, `data_inclusao`) VALUES (2, '2026-09-08 00:00:00', 'Reunião remota', 'Realizada call com colaboradores da São Pedro do Mar, e coordenadora Meri da Arquidiocese do Rio de Janeiro. A colaboradora Andrea Ruffo assumirá a coordenação paroquial.', 2, '2026-09-17 14:09:23');
INSERT INTO `paroquias_historico_relacionamento` (`id_paroquia`, `data`, `canal`, `detalhes`, `id_colaborador_atualiza`, `data_inclusao`) VALUES (38, '2026-09-19 00:00:00', 'Reunião presencial', 'Elisangela Passos fez reunião com Padre Walter sobre o Terço Mariano no dia 08/10/26 (Dia do Nascituro e aniversário de seis anos da Adoção Espiritual), transmitido pelo Rádio Catedral e Web Redentor.', 2, '2026-09-20 11:06:21');
INSERT INTO `paroquias_historico_relacionamento` (`id_paroquia`, `data`, `canal`, `detalhes`, `id_colaborador_atualiza`, `data_inclusao`) VALUES (207, '2026-09-13 00:00:00', 'Reunião presencial', 'As 16:00h, reunião com Mônica Passos e Cônego William Bernardo sobre Adoção Espiritual.', 2, '2026-09-20 11:17:02');
