INSERT INTO `pesquisas_satisfacao` (`id_pesquisa`, `id_colaborador`, `funcao`, `frequencia_uso`, `nota_navegacao`, `nota_visual`, `nota_celular`, `satisfacao_colaboradores`, `satisfacao_projetos`, `satisfacao_treinamentos`, `satisfacao_aniversariantes`, `frequencia_erros`, `nps`, `observacao`, `criado_em`, `recusado`) VALUES (11, 2, 'Administrador', 'Diariamente', 5, 5, NULL, 'Satisfeito', 'Satisfeito', 'Insatisfeito', 'Satisfeito', 'Raramente', 10, 'O portal mode ser melhorado com disponibilização de todas as funções em plataforma mobile', '2026-06-08 13:33:01', 0);
INSERT INTO `projetos` (`id_projeto`, `nome_projeto`, `id_area`, `data_inicio`, `data_fim`, `status`, `objetivo_projeto`, `observacoes`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (1, 'Prioridade 1 - Site institucional da Adoção Espiritual', 4, '2025-12-01 00:00:00', NULL, 'Em andamento', 'Atualizar o atual site com visual mais moderno e novos conteúdos', NULL, '2026-06-03 18:05:11', '2026-06-28 20:30:02', 2);
INSERT INTO `projetos` (`id_projeto`, `nome_projeto`, `id_area`, `data_inicio`, `data_fim`, `status`, `objetivo_projeto`, `observacoes`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (3, 'Portal colaboradores Adoção Espiritual', 4, '2026-02-20 00:00:00', '2026-08-31 00:00:00', 'Em andamento', 'Desenvolver aplicativo que facilite as atividades controladas em planilhas, permitindo melhor descentralização de atribuições e divulgação de informações', NULL, '2026-06-04 17:12:00', '2026-06-05 11:03:29', 2);
INSERT INTO `projetos` (`id_projeto`, `nome_projeto`, `id_area`, `data_inicio`, `data_fim`, `status`, `objetivo_projeto`, `observacoes`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (4, 'Prioridade 2 - Controle de senhas de e-mails e mídias sociais', 4, '2026-05-04 00:00:00', NULL, 'Não iniciado', 'Manter senhas individualizadas, permitindo conhecer quem realizou publicações nos canais sociais (Facebook, Instagram, Youtube, e-mail). Garantir troca de senhas a cada "x" meses.', NULL, '2026-06-11 10:18:00', '2026-06-28 20:30:02', 2);
INSERT INTO `projetos` (`id_projeto`, `nome_projeto`, `id_area`, `data_inicio`, `data_fim`, `status`, `objetivo_projeto`, `observacoes`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (5, 'Prioridade 3 - WhatsApp automatizado', 4, '2026-05-04 00:00:00', NULL, 'Não iniciado', 'Desenvolver perguntas automatizadas no WhatsApp permitindo conhecer a necessidade do usuário e por meio de suas respostas direcioná-lo para atendimento especializado.', 'Os telefones de direcionamento para o atendimento são privados e não deverão ser visualizados/conhecidos pelos usuários.', '2026-06-11 10:22:43', '2026-06-28 20:30:02', 2);
INSERT INTO `projetos` (`id_projeto`, `nome_projeto`, `id_area`, `data_inicio`, `data_fim`, `status`, `objetivo_projeto`, `observacoes`, `criado_em`, `atualizado_em`, `id_colaborador_atualiza`) VALUES (7, 'Prioridade 0 - Definição ambiente de hospedagem', 4, '2026-06-15 00:00:00', '2026-07-31 00:00:00', 'Em andamento', 'Definir a manutenção ou não do ambiente tecnológico da Adoção Espiritual no Hostinger', 'A licença atual vence em novembro de 2026 e tem um custo anual a ser verificado com Dom Tiago. Diácono Mário me informou que o seu cartão não está mais cadastrado para débito anual da licença.', '2026-06-15 11:43:04', '2026-06-17 19:15:37', 2);
